import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    a = data[1:1 + n]
    a.sort()

    ans = 0
    for k in range(2, n):
        target = a[k]
        i = 0
        j = k - 1

        while i < j:
            if a[i] + a[j] > target:
                ans += j - i
                j -= 1
            else:
                i += 1

    print(ans)

if __name__ == "__main__":
    main()
